tool_input.command:
mkdir -p migrations/down
cat > migrations/002_orders_amount_cents.sql <<'E'
-- Expand step of renaming orders.total_cents -> amount_cents. total_cents is dropped in a later deploy.
set lock_timeout = '5s';
alter table orders add column amount_cents integer;
alter table orders alter column total_cents drop not null;

create function orders_sync_amount_cents() returns trigger language plpgsql as $$
begin
  if tg_op = 'INSERT' then
    new.amount_cents := coalesce(new.amount_cents, new.total_cents);
    new.total_cents := coalesce(new.total_cents, new.amount_cents);
  elsif new.amount_cents is distinct from old.amount_cents then
    new.total_cents := new.amount_cents;
  elsif new.total_cents is distinct from old.total_cents then
    new.amount_cents := new.total_cents;
  end if;
  return new;
end $$;
create trigger orders_sync_amount_cents before insert or update on orders
  for each row execute function orders_sync_amount_cents();

alter table orders add constraint orders_amount_cents_not_null check (amount_cents is not null) not valid;
E
cat > migrations/down/002_orders_amount_cents.sql <<'E'
alter table orders drop constraint orders_amount_cents_not_null;
drop trigger orders_sync_amount_cents on orders;
drop function orders_sync_amount_cents();
update orders set total_cents = amount_cents where total_cents is null;
alter table orders alter column total_cents set not null;
alter table orders drop column amount_cents;
E
mkdir -p scripts
cat > scripts/backfill_orders_amount_cents.sql <<'E'
-- Run repeatedly until it reports UPDATE 0.
update orders set amount_cents = total_cents
where id in (select id from orders where amount_cents is null limit 5000);
E
sed -i '' 's/total_cents/amount_cents/' src/app.ts db/seed.sql
git status --short; cat package.json | grep -n migrate
